{
  "concepts": [
    {
      "conditions": [],
      "definition": "The workspace and its authoritative inputs persist across activations. Their current material state is the continuing truth surface for what the work has and has not done; work state preserves applicable valid work and outstanding obligations.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1471,
          "quote": "The workspace and its authoritative inputs persist across activations and\nare the continuing truth surface of the work: the surface whose current\nmaterial state decides what the work has and has not done.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F5.%20Work%20state%20and%20restart%2FThe%20workspace%20and%20an%20actor%27s%20account",
          "start_line": 1469
        }
      ],
      "key": "workspace_truth",
      "label": "Workspace truth surface"
    },
    {
      "conditions": [],
      "definition": "An actor's context is a bounded projection and revisable account of work state, disposable because closed results and needed step-produced facts are recorded before return. It is never another truth surface. Later intake reconstructs governing relations without a predecessor's private context.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1478,
          "quote": "An account is\nnever a second truth surface, and no later activation needs a prior\nactor's context: its intake reconstructs the governing relations without\nit",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F5.%20Work%20state%20and%20restart%2FThe%20workspace%20and%20an%20actor%27s%20account",
          "start_line": 1475
        }
      ],
      "key": "actor_account",
      "label": "Actor account"
    },
    {
      "conditions": [],
      "definition": "Proportionality relates material semantic ambiguity removed to effective reasoning complexity introduced. Complexity includes independent concepts and authority surfaces, cross-document joins, exceptions, branching, states, transitions, reconciled duplicates and decision detail; it is not line count, artifact count or context-window size. A detailed model may be proportional and a short extra truth surface disproportionate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1534,
          "quote": "Proportionality is the relation between semantic ambiguity removed and\neffective reasoning complexity introduced. A method obligation is\nproportional when its contraction of the admissible interpretation space\njustifies the additional concepts, relations, projections and evidence an\nactor must hold together to reach a correct decision",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F6.%20Cost%20and%20proportionality",
          "start_line": 1530
        }
      ],
      "key": "proportionality",
      "label": "Proportionality and effective reasoning complexity"
    },
    {
      "conditions": [
        "A cost claim is the governed question."
      ],
      "definition": "Selected cost is an activation's declared allowance and reported spend, measured under a selected execution binding or explicitly unmeasured. Material startup, framework processing, external computation, transport and assurance are separate components. Transferred-context cost includes every delegated actor, not merely coordinator traffic or report volume.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1592,
          "quote": "Cost is selected, not universal. Where a cost claim is the governed\nquestion, the activation declares its allowance and reports its spend,\nmeasured under the selected execution binding or recorded as unmeasured",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F6.%20Cost%20and%20proportionality",
          "start_line": 1589
        }
      ],
      "key": "selected_cost",
      "label": "Selected cost claim"
    },
    {
      "conditions": [],
      "definition": "A resource limit bounds context, attention, wall time, spend, human effort, communication or machine resources consumed by an activation. This subsection owns the generic declaration, measurement and exhaustion law but sets no values; the selected execution binding supplies values and measurable units and boundaries.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1643,
          "quote": "A resource limit bounds a resource that an activation consumes: context,\nattention, wall time, spend, human effort, communication or a machine\nresource (P0). This subsection owns the law for every such limit. It sets\nno value",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F6.%20Cost%20and%20proportionality%2FResource%20limits",
          "start_line": 1640
        }
      ],
      "key": "resource_limit",
      "label": "Declared resource limit"
    },
    {
      "conditions": [],
      "definition": "A closed result identifies its frame, activation, subject, basis, evaluation, actor, evidence, verdict, residual uncertainty and invalidation conditions. It supports handoff without private working context while retaining validity and independence conditions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1697,
          "quote": "A closed result identifies the frame and its activation, the subject, the\nbasis, the evaluation, the actor, the evidence, the verdict, the residual\nuncertainty and the invalidation conditions",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F7.%20Closed%20result%20and%20reuse",
          "start_line": 1694
        }
      ],
      "key": "closed_result",
      "label": "Closed result"
    },
    {
      "conditions": [],
      "definition": "Result invalidation has exactly three kinds: a material subject or relied-on input change, including admissible evidence capable of changing the result's value; change to any bound basis coordinate; and occurrence of an observation explicitly declared to revise the result or judgment. Affectedness is expressed as dependencies D*(t) meeting impact cover I(Δ). Invalidation withdraws direct reliance without deciding the underlying claim's truth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1732,
          "quote": "- a changed basis: a change to any coordinate of the basis the result\n  binds (FOUNDATIONS §2, Basis);\n- a declared revising observation: an observation that the result or\n  judgment itself names as one that would revise it, once it occurs.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F7.%20Closed%20result%20and%20reuse",
          "start_line": 1729
        }
      ],
      "key": "result_invalidation",
      "label": "Three kinds of result invalidation"
    },
    {
      "conditions": [],
      "definition": "Transition evidence is a consumer-chosen read model identifying the exact candidate, affected relations, changed realisation paths, authority paths added or removed, retained and open seams, focused proof, required integration proof and explicit non-changes. If an assessor was activated it includes the recommendation, with the decision owner's disposition beside it once made.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1770,
          "quote": "Transition evidence is a read\nmodel; it does not become specification, design or admission authority",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F7.%20Closed%20result%20and%20reuse%2FTransition%20evidence",
          "start_line": 1768
        }
      ],
      "key": "transition_evidence",
      "label": "Transition evidence"
    },
    {
      "conditions": [],
      "definition": "The source-disposition register states predecessor conservation, successor loci, new rules and pending proposals. It places UP-020 across activation, disposition, restart and transition evidence; UP-018 reconstruction in Intake and DESIGN_MODULE; probabilistic work commitments in FOUNDATIONS; RF engagement across activation and reuse; AC-010/011 and RF context laws in their owning successors; RF-012/AC-007 result algebra and result conjunction in FOUNDATIONS; ticket admission in ACTIVATION with TICKETS disposing its rows; ambiguity outcomes and hard stops in ACTIVATION with SPEC_METHOD ownership; general typed refinement in ACTIVATION while ODD 11.8 remains profile-specific; UP-017 in DESIGN_MODULE; UP-021 and ten standing-qualification forms in ACTIVATION §4; proportionality and cost in ACTIVATION, delivery in SPEC_METHOD and UP-005/019 in DESIGN_MODULE; generic result reuse in ACTIVATION and ticket continuity in TICKETS. The register calls workspace/account, foundation tables, transitions, configuration, effects, derived-surface staleness, parts of refinement, context acquisition/measurement, allowance and generic resource-limit rules new. These are reported source claims, not verified conservation judgments.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1788,
          "quote": "a table decides nothing and names the rule that states each consequence.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F8.%20Source%20dispositions",
          "start_line": 1788
        },
        {
          "end_line": 1808,
          "quote": "| Return A Closed Result | conserved; §7, which names the invalidators once as three kinds (material input change, with newly acquired or changed material evidence, from TICKET judgment continuity; changed basis; declared revising observation) and requires a domain trigger to be stated as an instance of one of them (new, with its purpose stated there) |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ACTIVATION.md#ACTIVATION%2F8.%20Source%20dispositions",
          "start_line": 1808
        }
      ],
      "key": "source_disposition_register",
      "label": "ACTIVATION predecessor-disposition register"
    },
    {
      "conditions": [],
      "definition": "ASSURANCE is a tier-2 document owning verification layers, testing taxonomy and its two proof authorities, portability, test authority, scenario bundles, installed proof, significant paths, testing frames, combinatorial value, path/debt erasure, evidence composition, subject acquisition, localisation and interface integration. It consumes tier-1 laws without redefining them. SPEC_METHOD supplies chain/change classes and PRODUCT_DEFINITION project bindings. It does not pre-empt design-profile module proof or TICKETS test-case authority and does not depend on the tier-3 Executive profile. rc.2 and baseline anchors are provenance only; received predecessor rules are stated to be restated for standalone use.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 20,
          "quote": "reuse); adds no definition to tier 1.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE",
          "start_line": 20
        },
        {
          "end_line": 36,
          "quote": "both are provenance only. Under the standalone successor requirement every\npredecessor row received here is restated in full in this text, and\nnothing here depends on that cut to be applied.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE",
          "start_line": 34
        }
      ],
      "key": "assurance_member",
      "label": "ASSURANCE document role"
    },
    {
      "conditions": [],
      "definition": "Requirements preserve invariant truth and ask what must be true; design preserves structural choice and asks how it is realised; scenarios preserve operational meaning and ask whether the realised system can do the claimed thing. Scenarios are the product-owner layer of concrete end-to-end use cases validating intent through realised behaviour, including whether a reusable unit can actually be built and applied twice.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 47,
          "quote": "| Requirements | invariant truth | what must be true? |\n| Design | structural choice | how is that truth realised? |\n| Scenarios | operational meaning | can the realised system actually do the claimed thing? |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F1.%20Verification%20layers",
          "start_line": 45
        }
      ],
      "key": "verification_layers",
      "label": "Requirements, design and scenario verification layers"
    },
    {
      "conditions": [
        "The applicable instance premises hold; commitments alone do not supply them."
      ],
      "definition": "F14 accounts for assurance and testing laws in §§1–16; §17 records dispositions and decides nothing. Its instance premises are a runnable/observable product in source and runnable forms, composition of modules/interfaces/owners along causal paths, user outcomes through supported surfaces, possible external workers/transports/fixtures and possibly design-governed module boundaries. Fourteen rows distinguish commitment-supported consequences from member-owned domain or policy choices and other owners. P0 is recovered; P1, P2, P3, P4a and P6 are marked independent; P5 is derived from P0/P6 with an open-world premise and P4b from P0/P2 with non-reacquirable step facts. The family records proof authorities, sandbox modes, fixture alternatives, scenario/path categories, installed-proof preference, four testing frames, path mutation policy, value coordinates, owner-issued subjects, four localisation forms, interface claims, module proof and lifecycle confirmation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 87,
          "quote": "decides what evidence proves a claim about a realised product and how\nthat evidence is organised. Its instance premises, which the commitments\ndo not supply, are named in the rows as follows: runnable product, a\nproduct's realisation can be executed or observed, in a source form and in\na deployed, installed or otherwise runnable form, to produce evidence;",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F1.%20Verification%20layers%2FFoundation%20to%20law%3A%20assurance%20and%20testing",
          "start_line": 83
        }
      ],
      "key": "assurance_foundation_family",
      "label": "F14 assurance and testing foundation-to-law family"
    },
    {
      "conditions": [],
      "definition": "Within urn:stdo:bounded-context:product-assurance, Product-level proof authority has two primary sources independent of execution breadth: design/module conformance and UAT/acceptance. Conformance derives from governing design, module ownership, declared carrier inventory or equivalent, structural diagrams where present and local fail-closed law; unit tests belong here, as may integration/negative/fail-closed tests targeting a designed boundary. Acceptance derives from requirements, acceptance criteria, scenarios/use cases and Product release/qualification claims. The shared context does not merge the design profile's module-proof authority with Product authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 162,
          "quote": "Authority source is not execution breadth. A test may be small or broad,\nfast or slow, deterministic or live, and still derives from one of two\nprimary authorities (P6, P1):\n\n1. design or module conformance tests; and\n2. UAT, or acceptance, tests.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F2.%20Testing%20strategy%20taxonomy",
          "start_line": 157
        }
      ],
      "key": "proof_authority_taxonomy",
      "label": "Two proof-authority sources"
    },
    {
      "conditions": [],
      "definition": "Sandbox UAT exercises a deployed, installed or otherwise runnable composed Product through declared application, public, runtime or control surfaces using a requirement-sourced scenario or acceptance case. Harnessed mode uses deterministic, fake, recorded or injected worker/result surfaces for reproducible composition, orchestration, control, projection, archive and scenario wiring. Live mode crosses a real configured external worker, tool, agent, service or probabilistic transport and returns evidence through declared result, evaluation, provenance and projection surfaces.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 197,
          "quote": "- harnessed sandbox UAT exercises the full composed product path with a\n  deterministic, fake, recorded or injected worker or result surface; and\n- live sandbox UAT exercises the full composed product path with a real\n  configured worker, tool, agent, service or other external probabilistic\n  transport where the product depends on that live boundary.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F2.%20Testing%20strategy%20taxonomy",
          "start_line": 193
        }
      ],
      "key": "sandbox_uat",
      "label": "Harnessed and live sandbox UAT"
    },
    {
      "conditions": [],
      "definition": "Fixture and proof portability makes required closure lanes reproducible from a declared source boundary. External project evidence is carried by a minimal checked-in fixture, a manifest naming external source/version/acquisition or binding rule, or classification outside required semantic closure.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 238,
          "quote": "- a minimal fixture is checked into the source boundary;\n- a fixture manifest declares the external source, version and\n  acquisition or binding rule; or\n- the test is classified as harnessed sandbox, live sandbox, reference\n  comparison or optional local evidence rather than required semantic\n  closure.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F2.%20Testing%20strategy%20taxonomy%2FFixture%20and%20proof%20portability",
          "start_line": 233
        }
      ],
      "key": "proof_portability",
      "label": "Fixture and proof portability"
    },
    {
      "conditions": [],
      "definition": "Written traceable test-case authority for a live requirement may contain scenario bundles, ordered sequences, negative/control cases and other evidence cases appropriate to the truth claimed. Each expected result carries assertion provenance: owning obligation, interpretation, assumptions, derivation, shared dependencies and whether its predicate is the obligation, a necessary condition or part of a sufficient conjunction.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 254,
          "quote": "Written authority includes the assertion\nprovenance of each expected result: the owning obligation, its\ninterpretation, assumptions, derivation and shared dependencies, and\nwhether the asserted predicate is the obligation, a necessary condition of\nit or part of a sufficient conjunction",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F3.%20Test%20authority",
          "start_line": 250
        }
      ],
      "key": "test_case_authority",
      "label": "Written test-case authority"
    },
    {
      "conditions": [],
      "definition": "A scenario bundle exposes the feature/use-case boundary, ordered test-case sequence and expected outcomes at significant steps. Scenarios make operational meaning inspectable and constrain intent/design by naming real boundaries, sequences, actors, controls and outcomes; the source calls them the best source for identifying significant code and control paths.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 274,
          "quote": "A scenario bundle shows the feature or use-case boundary being exercised,\nthe test-case sequence that proves it, and the outcomes expected at each\nsignificant step. It is the layer that makes operational meaning\ninspectable",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F4.%20Scenario%20bundle",
          "start_line": 271
        }
      ],
      "key": "scenario_bundle",
      "label": "Scenario bundle"
    },
    {
      "conditions": [
        "The system has an installable or runnable development form."
      ],
      "definition": "Installed-dev proof is the decisive lane against an installed development version treated as an independent project or external target, rather than source-tree-only proof.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 288,
          "quote": "Where a system has an installable or runnable development form, the\ndecisive proving lane runs against an installed development version as if\nit were an independent project or an externalised target, not only against\nthe source tree in place",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F5.%20Installed%20dev%20proof",
          "start_line": 285
        }
      ],
      "key": "installed_dev_proof",
      "label": "Installed development proof"
    },
    {
      "conditions": [],
      "definition": "Significant paths are the meaningful paths of the claimed behaviour. Usually, where relevant, they include success, fail-closed/rejection, boundary/control, integration/dispatch/transport and recovery/retry/replay. Exhaustive proof means intentional proof of named meaningful paths, not every branch in every file.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 308,
          "quote": "- the intended success path;\n- the fail-closed or rejection path;\n- the boundary or control path;\n- the integration, dispatch or transport path; and\n- the recovery, retry or replay path.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F6.%20Significant%20path%20coverage",
          "start_line": 304
        }
      ],
      "key": "significant_paths",
      "label": "Significant behaviour paths"
    },
    {
      "conditions": [],
      "definition": "The named ASSURANCE section grouping the Product testing frame set; this heading alone supplies no activation or frame declaration.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 315,
          "quote": "## 7. Product testing frame set",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set",
          "start_line": 315
        }
      ],
      "key": "testing_frame_set_section",
      "label": "Product testing frame set section"
    },
    {
      "conditions": [],
      "definition": "A testing frame executes or observes a declared subject to discriminate one exact claim using an explicit oracle, evidence population, path boundary and falsification condition. An authoritative Product path is the ordinary causal composition from supported entry through exact selected interfaces, owners, transitions, effects, persistence and recovery to the required outcome projection. Material combinatorial complexity is the claim-relative population of independent dimensions/interactions capable of changing outcomes, invariants, authority paths or failures; module laws and public module contracts belong at unit altitude, whereas cross-participant/Product/persistence/configuration/user-role combinations belong at broader congruent frames.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 322,
          "quote": "A testing frame is a frame (REFERENCE_FRAME §1) whose evaluation executes\nor observes a declared subject to discriminate one exact claim through an\nexplicit oracle, evidence population, path boundary and falsification\ncondition.",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FTerms",
          "start_line": 319
        },
        {
          "end_line": 340,
          "quote": "Material combinatorial complexity is the claim-relative population of\nindependent dimensions and interactions whose combinations can change an\noutcome, violate an invariant, select another authority path or expose a",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FTerms",
          "start_line": 338
        }
      ],
      "key": "testing_frame_terms",
      "label": "Testing frame, authoritative path and material combinations"
    },
    {
      "conditions": [
        "The governing frame configuration or admitted work authority selects testing frames for a Product promotion, closure or release-assurance claim."
      ],
      "definition": "A claim-relative frame configuration ordinarily assigns user outcomes to user acceptance, complete runnable causal paths to end-to-end, material composition boundaries and interactions to integration, and one module-owned law to unit. This is evidence assignment, not a role/stage/authority hierarchy or decomposition of frames. Placement makes laws available without adopting or activating them; ACTIVATION applicability decides activation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 358,
          "quote": "Placement in this member makes the\nset, and the law of §8 to §13 that serves it, available; it adopts nothing,\nand each activation is decided by ACTIVATION §1 (Applicability). The kind\nof runner does not select the frame; the evaluated claim, subject, path,\npopulation, oracle and falsification boundary do",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FThe%20set",
          "start_line": 354
        }
      ],
      "key": "frame_configuration",
      "label": "Claim-relative testing frame configuration"
    },
    {
      "conditions": [
        "Selected for an exact user-outcome claim."
      ],
      "definition": "User acceptance asks whether a declared user with admitted capability/information can obtain the exact Product-defined outcome through the ordinary supported surface. It binds the exact runnable Product; current Product, requirement, UX, identity, policy and acceptance authority; user role/environment and harnessed/live mode. Its manifold includes goals, entries, permissions, inputs, configuration, ordinary dependencies, declared substitutions, visible states/outputs, refusals, recovery and acceptance interval. Coordinates distinguish Product/artifact/install, role/capability, configuration/dependencies/mode, data/workspace/invocation/time/outcome/scenario. Evidence includes supported requests/responses, projections, claimed durable effects, refusals/recovery, scenario and subject/dependency identity. Its envelope supports acting and perceiving as that user and detecting hidden assistance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 415,
          "quote": "| evaluation family | Can a declared user, with the user's admitted capability and information, obtain the exact Product-defined outcome through the supported ordinary Product surface? |",
          "section_id": "repo://stdo-v3-generation-rc9/claude/c2cfa9b908d1722ae3f26c32fa4ece691083bdc3/source/standards/ASSURANCE.md#ASSURANCE%2F7.%20Product%20testing%20frame%20set%2FUser-acceptance%20frame",
          "start_line": 415
        }
      ],
      "key": "user_acceptance_frame",
      "label": "User-acceptance frame"
    },
    {
      "conditions": [
        "Selected for an exact complete runnable causal-path claim."
      ],
